130	    /**
131	     * Cache a value for the given hostname that will automatically expire once the TTL is reached.
132	     */
133	    final void cache(String hostname, E value, int ttl, EventLoop loop) {
134	        for (;;) {
135	            Entries entries = resolveCache.get(hostname);
136	            if (entries == null) {
137	                entries = new Entries(hostname);
138	                Entries oldEntries = resolveCache.putIfAbsent(hostname, entries);
139	                if (oldEntries != null) {
140	                    entries = oldEntries;
141	                }
142	            }
143	            if (entries.add(value, ttl, loop)) {
144	                break;
145	            }
