160	    /**
161	     * Returns {@code true} if this entry should replace all other entries that are already cached for the hostname.
162	     */
163	    protected abstract boolean shouldReplaceAll(E entry);
164	
165	    /**
166	     * Sort the {@link List} for a {@code hostname} before caching these.
167	     */
168	    protected void sortEntries(
169	            @SuppressWarnings("unused") String hostname, @SuppressWarnings("unused") List<E> entries) {
170	        // NOOP.
171	    }
172	
173	    /**
174	     * Returns {@code true} if both entries are equal.
175	     */
176	    protected abstract boolean equals(E entry, E otherEntry);
177	
178	    // Directly extend AtomicReference for intrinsics and also to keep memory overhead low.
179	    private final class Entries extends AtomicReference<List<E>> implements Runnable {
180	
181	        private final String hostname;
182	        // Needs to be package-private to be able to access it via the AtomicReferenceFieldUpdater
183	        volatile ScheduledFuture<?> expirationFuture;
184	
185	        Entries(String hostname) {
186	            super(Collections.<E>emptyList());
187	            this.hostname = hostname;
188	        }
189	
190	        boolean add(E e, int ttl, EventLoop loop) {
191	            // Fast-path: avoid mutating a dead Entries. scheduleCacheExpirationIfNeeded will
192	            // detect CANCELLED definitively, but checking early avoids unnecessary list writes
193	            // that could briefly re-expose evicted data to concurrent get() callers.
194	            if (FUTURE_UPDATER.get(this) == CANCELLED) {
195	                return false;
196	            }
197	            if (!shouldReplaceAll(e)) {
198	                for (;;) {
199	                    List<E> entries = get();
200	                    if (!entries.isEmpty()) {
201	                        final E firstEntry = entries.get(0);
202	                        if (shouldReplaceAll(firstEntry)) {
203	                            assert entries.size() == 1;
204	
205	                            if (compareAndSet(entries, singletonList(e))) {
206	                                return scheduleCacheExpirationIfNeeded(ttl, loop);
207	                            } else {
208	                                // Need to try again as CAS failed
209	                                continue;
210	                            }
211	                        }
212	
213	                        // Create a new List for COW semantics
214	                        List<E> newEntries = new ArrayList<E>(entries.size() + 1);
215	                        int i = 0;
216	                        E replacedEntry = null;
217	                        do {
218	                            E entry = entries.get(i);
219	                            // Only add old entry if the address is not the same as the one we try to add as well.
220	                            // In this case we will skip it and just add the new entry as this may have
221	                            // more up-to-date data and cancel the old after we were able to update the cache.
222	                            if (!Cache.this.equals(e, entry)) {
223	                                newEntries.add(entry);
224	                            } else {
225	                                replacedEntry = entry;
226	                                newEntries.add(e);
227	
228	                                ++i;
229	                                for (; i < entries.size(); ++i) {
230	                                    newEntries.add(entries.get(i));
231	                                }
232	                                break;
233	                            }
234	                        } while (++i < entries.size());
235	                        if (replacedEntry == null) {
236	                            newEntries.add(e);
237	                        }
238	                        sortEntries(hostname, newEntries);
239	
240	                        if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
241	                            return scheduleCacheExpirationIfNeeded(ttl, loop);
242	                        }
243	                    } else if (compareAndSet(entries, singletonList(e))) {
244	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
245	                    }
246	                }
247	            } else {
248	                List<E> newList = singletonList(e);
249	                set(newList);
250	                if (scheduleCacheExpirationIfNeeded(ttl, loop)) {
251	                    return true;
252	                }
253	                // CANCELLED detected: undo the write so zombie data is not briefly visible to
254	                // readers via get() during the window before resolveCache.remove() fires.
255	                compareAndSet(newList, Collections.<E>emptyList());
256	                return false;
257	            }
258	        }
259	
260	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
261	            for (;;) {
262	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
263	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
264	                // we can reconsider.
265	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
266	                if (oldFuture == CANCELLED) {
267	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
268	                    // Signal the caller (cache()) to retry with a fresh Entries.
269	                    return false;
270	                }
271	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
272	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
273	                    // It is possible that
274	                    // 1. task will fire in between this line, or
275	                    // 2. multiple timers may be set if there is concurrency
276	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
277	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
278	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
279	                        if (oldFuture != null) {
280	                            oldFuture.cancel(true);
281	                        }
282	                        return true;
283	                    } else {
284	                        // There was something else scheduled in the meantime... Cancel and try again.
285	                        newFuture.cancel(true);
286	                    }
287	                } else {
288	                    return true;
289	                }
290	            }
291	        }
292	
293	        boolean clearAndCancel() {
294	            // Set CANCELLED before clearing data so any concurrent scheduleCacheExpirationIfNeeded
295	            // call sees CANCELLED and returns false. If data were cleared first, a concurrent caller
296	            // could win the future CAS (CANCELLED not yet set), return true to cache(), and then
297	            // have its data immediately wiped when CANCELLED is set on the next step.
298	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
299	            List<E> entries = getAndSet(Collections.<E>emptyList());
300	            if (expirationFuture != null && expirationFuture != CANCELLED) {
301	                expirationFuture.cancel(false);
302	            }
303	            return !entries.isEmpty();
304	        }
305	
306	        @Override
307	        public void run() {
308	            // We always remove all entries for a hostname once one entry expire. This is not the
309	            // most efficient to do but this way we can guarantee that if a DnsResolver
310	            // be configured to prefer one ip family over the other we will not return unexpected
311	            // results to the enduser if one of the A or AAAA records has different TTL settings.
312	            //
313	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
314	            // completely fine to remove the entry even if the TTL is not reached yet.
315	            //
316	            // See https://github.com/netty/netty/issues/7329
317	            // Set CANCELLED before removing from the map so any concurrent scheduleCacheExpirationIfNeeded
318	            // call always sees CANCELLED and returns false (triggering a retry in cache()) rather than
319	            // succeeding its future CAS, returning true, and having the data wiped immediately after.
320	            clearAndCancel();
321	
322	            resolveCache.remove(hostname, this);
323	        }
324	    }
325	}
