28	/**
29	 * {@link OpenSslSessionCache} that is used by the client-side.
30	 */
31	final class OpenSslClientSessionCache extends OpenSslSessionCache {
32	    private final Map<HostPort, Set<NativeSslSession>> sessions = new HashMap<>();
33	
34	    OpenSslClientSessionCache(OpenSslEngineMap engines) {
35	        super(engines);
36	    }
37	
38	    @Override
39	    protected boolean sessionCreated(NativeSslSession session) {
40	        assert Thread.holdsLock(this);
41	        HostPort hostPort = keyFor(session.getPeerHost(), session.getPeerPort());
42	        if (hostPort == null) {
43	            return false;
44	        }
45	        Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
46	        if (sessionsForHost == null) {
47	            // Let's start with something small as usually the server does not provide too many of these per hostPort
48	            // mapping.
49	            sessionsForHost = new HashSet<>(4);
50	            sessions.put(hostPort, sessionsForHost);
51	        }
52	        sessionsForHost.add(session);
53	        return true;
54	    }
55	
56	    @Override
57	    protected void sessionRemoved(NativeSslSession session) {
58	        assert Thread.holdsLock(this);
59	        HostPort hostPort = keyFor(session.getPeerHost(), session.getPeerPort());
60	        if (hostPort == null) {
61	            return;
62	        }
63	        Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
64	        if (sessionsForHost != null) {
65	            sessionsForHost.remove(session);
66	            if (sessionsForHost.isEmpty()) {
67	                sessions.remove(hostPort);
68	            }
69	        }
70	    }
71	
72	    @Override
73	    boolean setSession(long ssl, OpenSslInternalSession session, String host, int port) {
74	        HostPort hostPort = keyFor(host, port);
75	        if (hostPort == null) {
76	            return false;
77	        }
78	        final boolean reused;
79	        boolean singleUsed = false;
80	        long capturedCreationTime = 0;
81	        long capturedLastAccessedTime = 0;
82	        OpenSslSessionId capturedSessionId = null;
83	        Map<String, Object> capturedKeyValueStorage = null;
84	        synchronized (this) {
85	            Set<NativeSslSession> sessionsForHost = sessions.get(hostPort);
86	            if (sessionsForHost == null) {
87	                return false;
88	            }
89	            if (sessionsForHost.isEmpty()) {
90	                sessions.remove(hostPort);
91	                // There is no session that we can use.
92	                return false;
93	            }
94	
95	            NativeSslSession nativeSslSession = null;
96	            List<NativeSslSession> toBeRemoved = null;
97	            // Loop through all the sessions that might be usable and check if we can use one of these.
98	            for (NativeSslSession sslSession : sessionsForHost) {
99	                if (sslSession.isValid()) {
100	                    nativeSslSession = sslSession;
101	                    break;
102	                } else {
103	                    if (toBeRemoved == null) {
104	                        toBeRemoved = new ArrayList<>(2);
105	                    }
106	                    toBeRemoved.add(sslSession);
107	                }
108	            }
109	
110	            // Remove everything that is not valid anymore
111	            if (toBeRemoved != null) {
112	                for (NativeSslSession sslSession : toBeRemoved) {
113	                    removeSessionWithId(sslSession.sessionId());
114	                }
115	            }
116	            if (nativeSslSession == null) {
117	                // Couldn't find a valid session that could be used.
118	                return false;
119	            }
120	
121	            // Try to set the session, if true is returned OpenSSL incremented the reference count
122	            // of the underlying SSL_SESSION*.
123	            reused = SSL.setSession(ssl, nativeSslSession.session());
124	            if (reused) {
125	                singleUsed = nativeSslSession.shouldBeSingleUse();
126	                // Capture all Java-heap fields before any removal. removeSessionWithId frees the
127	                // native SSL_SESSION* pointer, but the Java wrapper's plain fields remain readable.
128	                // Capturing here also means setLastAccessedTime is always recorded for resumed sessions.
129	                long now = System.currentTimeMillis();
130	                nativeSslSession.setLastAccessedTime(now);
131	                capturedCreationTime = nativeSslSession.getCreationTime();
132	                capturedLastAccessedTime = now;
133	                capturedSessionId = nativeSslSession.sessionId();
134	                capturedKeyValueStorage = nativeSslSession.keyValueStorage;
135	                if (singleUsed) {
136	                    // Remove while holding the lock so no concurrent thread can pick up this single-use ticket.
137	                    removeSessionWithId(nativeSslSession.sessionId());
138	                }
139	            }
140	        }
141	
142	        if (reused) {
143	            if (singleUsed) {
144	                session.invalidate();
145	            }
146	            session.setSessionDetails(capturedCreationTime, capturedLastAccessedTime,
147	                    capturedSessionId, capturedKeyValueStorage);
148	        }
149	        return reused;
150	    }
151	
152	    private static HostPort keyFor(String host, int port) {
153	        if (host == null && port < 1) {
154	            return null;
155	        }
156	        return new HostPort(host, port);
157	    }
158	
159	    @Override
160	    synchronized void clear() {
161	        super.clear();
162	        sessions.clear();
163	    }
164	
165	    /**
166	     * Host / Port tuple used to find a {@link OpenSslInternalSession} in the cache.
167	     */
168	    private static final class HostPort {
169	        private final int hash;
170	        private final String host;
171	        private final int port;
172	
173	        HostPort(String host, int port) {
174	            this.host = host;
175	            this.port = port;
176	            // Calculate a hashCode that does ignore case. Use -1 for null host to avoid colliding
177	            // with non-null hosts whose AsciiString.hashCode happens to be 0.
178	            this.hash = 31 * (host != null ? AsciiString.hashCode(host) : -1) + port;
179	        }
180	
181	        @Override
182	        public int hashCode() {
183	            return hash;
184	        }
185	
186	        @Override
187	        public boolean equals(Object obj) {
188	            if (!(obj instanceof HostPort)) {
189	                return false;
190	            }
191	            HostPort other = (HostPort) obj;
192	            return port == other.port &&
193	                    (host == null ? other.host == null : host.equalsIgnoreCase(other.host));
194	        }
195	
196	        @Override
197	        public String toString() {
198	            return "HostPort{" +
199	                    "host='" + host + '\'' +
200	                    ", port=" + port +
201	                    '}';
202	        }
203	    }
204	}
