Entries(String hostname) {
    super(Collections.<E>emptyList());
    this.hostname = hostname;
}

boolean add(E e, int ttl, EventLoop loop) {
    // Fast-path: avoid mutating a dead Entries. scheduleCacheExpirationIfNeeded will
    // detect CANCELLED definitively, but checking early avoids unnecessary list writes
    // that could briefly re-expose evicted data to concurrent get() callers.
    if (FUTURE_UPDATER.get(this) == CANCELLED) {
        return false;
    }
    if (!shouldReplaceAll(e)) {
        for (;;) {
            List<E> entries = get();
            if (!entries.isEmpty()) {
                final E firstEntry = entries.get(0);
                if (shouldReplaceAll(firstEntry)) {
                    assert entries.size() == 1;

                    if (compareAndSet(entries, singletonList(e))) {
                        return scheduleCacheExpirationIfNeeded(ttl, loop);
                    } else {
                        // Need to try again as CAS failed
                        continue;
                    }
                }

                // Create a new List for COW semantics
                List<E> newEntries = new ArrayList<E>(entries.size() + 1);
                int i = 0;
                E replacedEntry = null;
                do {
                    E entry = entries.get(i);
                    // Only add old entry if the address is not the same as the one we try to add as well.
                    // In this case we will skip it and just add the new entry as this may have
                    // more up-to-date data and cancel the old after we were able to update the cache.
                    if (!Cache.this.equals(e, entry)) {
                        newEntries.add(entry);
                    } else {
                        replacedEntry = entry;
                        newEntries.add(e);

                        ++i;
                        for (; i < entries.size(); ++i) {
                            newEntries.add(entries.get(i));
                        }
                        break;
                    }
                } while (++i < entries.size());
                if (replacedEntry == null) {
                    newEntries.add(e);
                }
                sortEntries(hostname, newEntries);

                if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
                    return scheduleCacheExpirationIfNeeded(ttl, loop);
                }
            } else if (compareAndSet(entries, singletonList(e))) {
                return scheduleCacheExpirationIfNeeded(ttl, loop);
            }
        }
    } else {
        List<E> newList = singletonList(e);
        set(newList);
        if (scheduleCacheExpirationIfNeeded(ttl, loop)) {
            return true;
        }
        // CANCELLED detected: undo the write so zombie data is not briefly visible to
        // readers via get() during the window before resolveCache.remove() fires.
        compareAndSet(newList, Collections.<E>emptyList());
        return false;
    }
}

